.square-btn:hover{background:rgba(217,255,67,.09);border-color:rgba(217,255,67,.38)}
.square-btn span{font-size:18px;line-height:1;color:var(--acid)}
.square-btn small{font-size:6.5px;letter-spacing:.1em;line-height:1.3;text-align:center;color:#9eada7}

.operator-panel{position:absolute;right:clamp(22px,4vw,64px);bottom:20px;width:min(365px,30vw);z-index:5;padding:18px 20px 14px;background:linear-gradient(160deg,rgba(7,14,17,.76),rgba(7,14,17,.4));border-right:1px solid rgba(217,255,67,.28);border-top:1px solid rgba(255,255,255,.1);clip-path:polygon(0 0,100% 0,100% 100%,16px 100%,0 calc(100% - 16px),0 18px);backdrop-filter:blur(6px)}
.operator-panel::before{content:"";position:absolute;right:-1px;top:0;width:1px;height:45%;background:var(--acid);box-shadow:0 0 14px var(--acid)}
.operator-topline{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line-soft);padding-bottom:8px;margin-bottom:11px}
.tiny-label{font-size:8px;letter-spacing:.22em;color:#8fa19b;font-weight:700}
.operator-id{font-family:var(--font-display);font-size:14px;color:var(--acid);letter-spacing:.06em}
.char-role{font-size:8px;letter-spacing:.2em;color:var(--orange);font-weight:800;margin-bottom:5px}
.operator-copy h2{font-family:var(--font-display);font-size:clamp(20px,2vw,29px);letter-spacing:.02em;line-height:1;margin-bottom:9px;text-shadow:0 2px 10px rgba(0,0,0,.8)}
.operator-copy p{font-size:10px;line-height:1.55;color:#b0bfb9;min-height:47px}
.char-stats{display:flex;gap:10px;margin-top:11px}
.stat{flex:1}
.stat span{display:block;font-size:6.5px;letter-spacing:.14em;color:#84968f;margin-bottom:4px}
.stat i{display:block;height:3px;background:rgba(255,255,255,.12)}
.stat i b{display:block;height:100%;background:linear-gradient(90deg,var(--acid),var(--cyan))}
.anim-buttons{display:flex;gap:4px;margin-top:13px}
.anim-buttons button{flex:1;padding:5px 3px;font-size:7px;letter-spacing:.1em;color:#93a49e;border:1px solid rgba(255,255,255,.08);background:rgba(4,10,12,.4)}
.anim-buttons button:hover,.anim-buttons button.active{color:var(--acid);border-color:rgba(217,255,67,.4);background:rgba(217,255,67,.08)}
.operator-pager{display:flex;align-items:center;justify-content:space-between;margin-top:11px}
.operator-pager button{width:28px;height:22px;border:1px solid var(--line-soft);color:var(--acid);font-size:16px;line-height:1}
.operator-pager button:hover{background:rgba(217,255,67,.1)}
.operator-dots{display:flex;gap:4px}
.operator-dots i{width:5px;height:5px;background:rgba(255,255,255,.19);transform:skewX(-18deg);cursor:pointer}
.operator-dots i.active{background:var(--acid);box-shadow:0 0 7px rgba(217,255,67,.7);width:14px}

.menu-bottom{position:relative;z-index:5;display:flex;align-items:center;gap:22px;padding:12px clamp(22px,4vw,64px) 18px;padding-bottom:calc(18px + var(--safe-bottom));background:linear-gradient(0deg,rgba(3,8,10,.9),rgba(3,8,10,.15));border-top:1px solid rgba(255,255,255,.06)}
.loadout-strip{display:flex;align-items:center;gap:12px;flex:1;min-width:0}
.loadout-label{display:flex;flex-direction:column;gap:3px;border-left:2px solid var(--acid);padding-left:9px}
.loadout-label span{font-size:7px;letter-spacing:.2em;color:var(--muted)}
.loadout-label b{font-size:9px;letter-spacing:.15em}
.weapon-slot{display:flex;align-items:center;gap:11px;padding:5px 10px 5px 5px;min-width:270px;max-width:330px;border:1px solid rgba(255,255,255,.08);background:rgba(9,17,20,.5);text-align:left;transition:border-color .15s,background .15s}
.weapon-slot:hover{border-color:rgba(217,255,67,.4);background:rgba(217,255,67,.05)}
.weapon-silhouette{width:76px;height:35px;background:linear-gradient(160deg,rgba(217,255,67,.14),rgba(0,0,0,.2));display:grid;place-items:center;border:1px solid rgba(255,255,255,.07);position:relative;overflow:hidden}
.weapon-silhouette svg{width:70px;height:26px;filter:drop-shadow(0 0 5px rgba(217,255,67,.2))}
.weapon-slot b{display:block;font-size:10px;letter-spacing:.1em}
.weapon-slot span{display:block;font-size:7.5px;letter-spacing:.07em;color:#889a93;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.weapon-slot i{margin-left:auto;font-style:normal;color:var(--acid);font-size:17px;opacity:.7}
.loadout-divider{width:1px;height:35px;background:var(--line-soft)}
.loadout-meta{display:flex;flex-direction:column;gap:3px;min-width:48px}
.loadout-meta span{font-size:6.5px;letter-spacing:.12em;color:var(--muted)}
.loadout-meta b{font-size:12px;color:var(--acid)}
.bottom-nav{display:flex;gap:4px}
.bottom-nav button{position:relative;padding:8px 10px;font-size:8px;font-weight:800;letter-spacing:.12em;color:#8fa19a;border-bottom:1px solid transparent}
.bottom-nav button b{color:var(--acid);font-size:7px;margin-left:2px}
.bottom-nav button:hover,.bottom-nav button.active{color:#eaf2ea;border-bottom-color:var(--acid);background:linear-gradient(0deg,rgba(217,255,67,.07),transparent)}
.build-tag{font-size:6.5px;letter-spacing:.13em;color:#556762;text-align:right;white-space:nowrap}
.build-tag span{display:block;color:rgba(217,255,67,.6);margin-top:2px}

/* ============================== MODALS ============================== */
.modal-layer{position:absolute;inset:0;z-index:50;display:grid;place-items:center;padding:3vh 3vw}
#modal-backdrop{position:absolute;inset:0;background:rgba(2,6,8,.78);backdrop-filter:blur(8px)}
.modal-panel{position:relative;width:min(1120px,96vw);max-height:90vh;overflow:auto;padding:24px 28px 26px;background:linear-gradient(150deg,rgba(13,23,27,.98),rgba(5,11,14,.98));border:1px solid rgba(217,255,67,.24);box-shadow:0 30px 90px rgba(0,0,0,.7),inset 0 0 80px rgba(217,255,67,.025);clip-path:polygon(0 0,calc(100% - 22px) 0,100% 22px,100% 100%,22px 100%,0 calc(100% - 22px))}
.modal-panel::before{content:"";position:absolute;left:0;top:0;width:80px;height:3px;background:var(--acid)}
.modal-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:20px;padding-bottom:13px;border-bottom:1px solid var(--line-soft)}
.modal-head h2{font-family:var(--font-display);font-size:clamp(18px,2.2vw,29px);letter-spacing:.02em;margin-top:4px}
.modal-actions{display:flex;align-items:center;gap:14px}
.modal-actions>span{font-size:8px;letter-spacing:.15em;color:#8fa19b}
.close-modal{width:32px;height:32px;border:1px solid rgba(255,255,255,.12);color:#aebdb6;font-size:13px}
.close-modal:hover{border-color:var(--orange);color:var(--orange);background:rgba(255,122,61,.08)}
.roster-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}
.char-card{position:relative;background:linear-gradient(160deg,rgba(19,32,36,.9),rgba(6,12,15,.9));border:1px solid rgba(255,255,255,.09);padding:0 0 9px;overflow:hidden;clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%);transition:transform .15s,border-color .15s}
.char-card:hover{transform:translateY(-3px);border-color:rgba(217,255,67,.45)}
.char-card.selected{border-color:var(--acid);box-shadow:0 0 0 1px rgba(217,255,67,.3),0 0 24px rgba(217,255,67,.08)}
.char-card.selected::before{content:"SELECIONADO";position:absolute;top:7px;left:7px;z-index:2;padding:3px 5px;background:var(--acid);color:#0a1110;font-size:6px;font-weight:900;letter-spacing:.08em}
.char-card img{display:block;width:100%;aspect-ratio:1/1.08;object-fit:cover;background:#0a1418;border-bottom:1px solid rgba(255,255,255,.07)}
.char-card b{display:block;font-size:9px;letter-spacing:.05em;padding:7px 8px 2px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.char-card span{display:block;font-size:6.5px;letter-spacing:.1em;color:#81928d;padding:0 8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.char-card .char-num{position:absolute;top:8px;right:8px;font-family:var(--font-display);font-size:11px;color:rgba(255,255,255,.28);z-index:2}

.arsenal-layout{display:grid;grid-template-columns:1.3fr .7fr;gap:24px}
.weapon-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.weapon-card{position:relative;display:flex;align-items:center;gap:12px;padding:12px;border:1px solid rgba(255,255,255,.09);background:rgba(9,17,20,.54);text-align:left;clip-path:polygon(0 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%)}
.weapon-card:hover{border-color:rgba(217,255,67,.4);background:rgba(217,255,67,.05)}
.weapon-card.selected{border-color:var(--acid);background:linear-gradient(120deg,rgba(217,255,67,.12),rgba(9,17,20,.5))}
.weapon-card svg{width:105px;height:45px;flex:0 0 105px;filter:drop-shadow(0 0 8px rgba(217,255,67,.18))}
.weapon-card b{display:block;font-size:11px;letter-spacing:.08em}
.weapon-card span{display:block;font-size:7.5px;color:#84968f;margin-top:3px;letter-spacing:.08em}
.weapon-card i{font-style:normal;font-size:7px;color:var(--orange);position:absolute;top:8px;right:9px;letter-spacing:.1em}
.skin-panel{border-left:1px solid var(--line-soft);padding-left:22px}
.skin-preview{height:170px;display:grid;place-items:center;position:relative;background:radial-gradient(ellipse at center,rgba(217,255,67,.1),transparent 67%),linear-gradient(160deg,rgba(255,255,255,.03),rgba(0,0,0,.18));border:1px solid rgba(255,255,255,.07);margin-bottom:12px;overflow:hidden}
.skin-preview::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 19px,rgba(255,255,255,.03) 19px 20px)}
.gun-big{width:82%;position:relative;z-index:1;filter:drop-shadow(0 14px 12px rgba(0,0,0,.55))}
.gun-big svg{width:100%;height:auto}
.skin-preview>span{position:absolute;bottom:8px;right:10px;font-family:var(--font-display);font-size:13px;letter-spacing:.1em;color:rgba(217,255,67,.85);z-index:2}
.skin-swatches{display:flex;gap:7px;margin:9px 0 18px}
.skin-swatch{width:34px;height:34px;border:1px solid rgba(255,255,255,.16);position:relative;transition:transform .12s,border-color .12s}
.skin-swatch:hover{transform:translateY(-2px)}
.skin-swatch.selected{border-color:var(--acid);box-shadow:0 0 12px rgba(217,255,67,.25)}
.skin-swatch.selected::after{content:"✓";position:absolute;inset:0;display:grid;place-items:center;color:#fff;font-size:12px;text-shadow:0 1px 3px #000}
.weapon-stats{display:grid;gap:8px}
.weapon-stats .stat span{font-size:7px}
.weapon-stats .stat i{height:4px}

.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 34px}
.setting{display:flex;flex-direction:column;gap:9px}
.setting label{display:flex;justify-content:space-between;font-size:8px;font-weight:800;letter-spacing:.16em;color:#9db0a9}
.setting label b{color:var(--acid)}
.setting input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:3px;background:rgba(255,255,255,.17);outline:none}
.setting input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;background:var(--acid);border-radius:0;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%);cursor:pointer}
.segmented{display:flex;gap:4px}
.segmented button{flex:1;padding:8px;font-size:8px;font-weight:800;letter-spacing:.1em;color:#84968f;border:1px solid rgba(255,255,255,.1);background:rgba(7,13,16,.6)}
.segmented button:hover{border-color:rgba(217,255,67,.3)}
.segmented button.active{color:var(--acid);border-color:rgba(217,255,67,.5);background:rgba(217,255,67,.09)}
.setting-wide{grid-column:1/-1}
.settings-note{font-size:10px;line-height:1.65;color:#91a39c}
.modal-footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px;padding-top:16px;border-top:1px solid var(--line-soft)}
.btn-primary,.btn-secondary{position:relative;padding:12px 22px;font-size:10px;font-weight:900;letter-spacing:.14em;clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%);transition:transform .14s,background .14s,border-color .14s}
.btn-primary{background:var(--acid);color:#0a1110}
.btn-primary:hover{background:#e7ff7b;transform:translateY(-1px)}
.btn-secondary{border:1px solid rgba(255,255,255,.16);color:#c4d1ca;background:rgba(9,17,20,.4)}
.btn-secondary:hover{border-color:var(--acid);color:var(--acid);background:rgba(217,255,67,.06)}
.btn-secondary.danger:hover{border-color:var(--red);color:var(--red);background:rgba(255,59,79,.07)}

.custom-grid{display:grid;grid-template-columns:1fr 1fr .72fr;gap:25px}
.custom-col{display:flex;flex-direction:column;gap:9px}
.custom-options{display:flex;flex-direction:column;gap:5px;margin-bottom:8px}
.custom-options button{padding:9px 12px;text-align:left;font-size:9px;font-weight:800;letter-spacing:.1em;color:#92a39d;border:1px solid rgba(255,255,255,.08);background:rgba(8,15,18,.5)}
.custom-options button:hover{border-color:rgba(217,255,67,.35)}
.custom-options button.active{color:var(--acid);border-color:rgba(217,255,67,.5);background:rgba(217,255,67,.08)}
.custom-maps{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.range-line{display:flex;align-items:center;gap:12px;margin-bottom:10px}
.range-line input{flex:1;accent-color:var(--acid)}
.range-line b{min-width:52px;font-size:11px;color:var(--acid);text-align:right}
.room-code{padding:14px;background:rgba(217,255,67,.06);border:1px dashed rgba(217,255,67,.35);font-family:var(--font-display);font-size:23px;letter-spacing:.15em;color:var(--acid);text-align:center}
.custom-summary{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:10px;padding:20px;background:linear-gradient(165deg,rgba(255,122,61,.1),rgba(7,14,17,.4));border:1px solid rgba(255,122,61,.18);text-align:center;clip-path:polygon(0 0,100% 0,100% calc(100% - 14px),calc(100% - 14px) 100%,0 100%)}
.summary-badge{width:62px;height:62px;display:grid;place-items:center;font-size:28px;border-radius:50%;background:rgba(255,122,61,.14);border:1px solid rgba(255,122,61,.3)}
.custom-summary h3{font-family:var(--font-display);font-size:18px;letter-spacing:.05em}
.custom-summary p{font-size:9px;line-height:1.5;color:#94a59f;margin-bottom:5px}

.how-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}
.how-card{padding:16px;background:rgba(8,15,18,.52);border:1px solid rgba(255,255,255,.08);clip-path:polygon(0 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%)}
.how-card b{font-family:var(--font-display);font-size:20px;color:var(--acid);opacity:.8}
.how-card h3{font-size:11px;letter-spacing:.12em;margin:8px 0 7px}
.how-card p{font-size:9.5px;line-height:1.65;color:#91a49c}

.map-detail-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.map-detail{background:rgba(8,15,18,.6);border:1px solid rgba(255,255,255,.09);padding:0 0 12px;overflow:hidden;cursor:pointer;transition:transform .15s,border-color .15s}
.map-detail:hover{transform:translateY(-3px);border-color:rgba(217,255,67,.4)}
.map-detail img{width:100%;aspect-ratio:1/1;object-fit:cover;border-bottom:1px solid rgba(255,255,255,.08)}
.map-detail b{display:block;font-size:10px;letter-spacing:.08em;padding:9px 10px 3px}
.map-detail p{font-size:8px;line-height:1.5;color:#879a93;padding:0 10px}
.map-detail span{display:block;font-size:7px;color:var(--orange);letter-spacing:.1em;padding:6px 10px 0}

/* ============================== LOADING ============================== */
#loading-screen{z-index:40;background:radial-gradient(ellipse at 50% 60%,rgba(255,122,61,.13),transparent 50%),linear-gradient(150deg,#0b171b,#04090b 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;overflow:hidden}
#loading-screen::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 70px,rgba(217,255,67,.025) 70px 72px)}
.vs-bg{position:absolute;width:70vw;height:70vw;max-width:900px;max-height:900px;border:1px solid rgba(217,255,67,.08);border-radius:50%;box-shadow:0 0 0 80px rgba(217,255,67,.018),0 0 0 160px rgba(255,122,61,.012);animation:spin 40s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.loading-top{position:absolute;top:6vh;left:0;right:0;display:flex;justify-content:center;align-items:center;gap:22px;font-size:8px;letter-spacing:.23em;color:#7c8e88}
.loading-top b{color:#e9f0e8;font-size:11px;letter-spacing:.18em}
.vs-wrap{position:relative;z-index:2;display:flex;align-items:center;gap:clamp(30px,7vw,110px);text-align:center}
.vs-team h2{font-family:var(--font-display);font-size:clamp(21px,3vw,40px);line-height:1;margin:8px 0}
.vs-team p{font-size:9px;letter-spacing:.1em;color:#81938c}
.vs-blue h2{color:var(--cyan)}
.vs-orange h2{color:var(--orange)}
.vs-mark{font-family:var(--font-display);font-size:clamp(42px,7vw,92px);color:var(--acid);transform:skewX(-7deg);text-shadow:0 0 30px rgba(217,255,67,.24)}
.loading-bar{position:relative;z-index:2;width:min(460px,76vw);height:3px;background:rgba(255,255,255,.12);margin-top:10px}
.loading-bar i{display:block;width:0%;height:100%;background:var(--acid);box-shadow:0 0 12px var(--acid);transition:width .18s}
.loading-status{position:relative;z-index:2;font-size:8px;letter-spacing:.24em;color:#a6b7b0}
.loading-tip{position:absolute;bottom:5vh;left:0;right:0;text-align:center;font-size:8px;letter-spacing:.08em;color:#60736c;padding:0 20px}

/* ============================== MATCH HUD ============================== */
#match-ui{position:absolute;inset:0;z-index:12;pointer-events:none;font-family:var(--font-ui)}
.top-hud{position:absolute;top:calc(14px + var(--safe-top));left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:2px;filter:drop-shadow(0 5px 15px rgba(0,0,0,.5))}
.team-score{display:flex;align-items:center;gap:9px;padding:6px 12px;background:rgba(5,11,14,.72);border:1px solid rgba(255,255,255,.08);backdrop-filter:blur(4px)}
.team-score.blue{border-right:0;clip-path:polygon(12px 0,100% 0,100% 100%,0 100%,0 12px)}
.team-score.orange{border-left:0;clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%)}
.team-score b{font-family:var(--font-display);font-size:20px;line-height:1;min-width:22px;text-align:center}
.team-score.blue b{color:var(--cyan)}
.team-score.orange b{color:var(--orange)}
.team-label{font-size:7px;font-weight:900;letter-spacing:.18em;color:#95a7a0}
.team-score i{display:block;width:58px;height:2px;background:rgba(255,255,255,.13)}
.team-score i em{display:block;height:100%;width:0%;transition:width .35s}
.team-score.blue i em{background:var(--cyan)}
.team-score.orange i em{background:var(--orange)}
.match-center{display:flex;flex-direction:column;align-items:center;padding:4px 18px 5px;background:rgba(4,9,11,.84);border-top:1px solid rgba(217,255,67,.26);border-bottom:1px solid rgba(217,255,67,.1);min-width:122px}
.match-center span{font-size:6.5px;letter-spacing:.2em;color:var(--acid)}
.match-center b{font-family:var(--font-display);font-size:21px;letter-spacing:.06em;line-height:1.08}
.match-center small{font-size:6px;letter-spacing:.15em;color:#7e9189;margin-top:1px}
.pause-btn{pointer-events:auto;margin-left:10px;width:31px;height:31px;border:1px solid rgba(255,255,255,.15);background:rgba(5,11,14,.65);color:#b9c8c1;font-size:10px}
.pause-btn:hover{border-color:var(--acid);color:var(--acid)}
.minimap-wrap{position:absolute;top:calc(74px + var(--safe-top));left:18px;display:flex;flex-direction:column;gap:5px}
.minimap-ring{position:relative;width:124px;height:124px;border-radius:50%;background:rgba(4,11,13,.6);border:1px solid rgba(217,255,67,.28);box-shadow:inset 0 0 30px rgba(0,0,0,.65),0 5px 15px rgba(0,0,0,.4);overflow:hidden}
.minimap-ring::after{content:"";position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,transparent 55%,rgba(3,8,10,.55));pointer-events:none}
#minimap{width:100%;height:100%;border-radius:50%}
.north{position:absolute;top:4px;left:50%;transform:translateX(-50%);font-size:6px;color:var(--acid);letter-spacing:.1em;z-index:2}
.zone-chips{display:flex;gap:3px}
.zone-chip{flex:1;padding:3px 4px;font-size:6.5px;font-weight:900;text-align:center;background:rgba(5,11,14,.7);border:1px solid rgba(255,255,255,.1);color:#92a29c}
.zone-chip.blue{border-color:rgba(72,183,255,.55);color:var(--blue)}
.zone-chip.orange{border-color:rgba(255,122,61,.55);color:var(--orange)}
.zone-chip.contested{border-color:var(--acid);color:var(--acid);animation:blink 0.7s steps(2) infinite}
@keyframes blink{50%{opacity:.35}}

.killfeed{position:absolute;top:calc(76px + var(--safe-top));right:22px;display:flex;flex-direction:column;align-items:flex-end;gap:4px;max-width:300px}
.kill-item{display:flex;align-items:center;gap:6px;padding:4px 8px;background:rgba(4,9,11,.7);border-right:2px solid rgba(255,255,255,.22);font-size:8px;letter-spacing:.04em;animation:feedIn .22s ease-out}
@keyframes feedIn{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}
.kill-item .killer{color:var(--cyan);font-weight:800}
.kill-item .victim{color:var(--orange);font-weight:800}
.kill-item .k-weap{color:#7f928a;font-size:7px}
.kill-item .k-head{color:var(--acid);font-size:9px}
.kill-item.you{background:rgba(217,255,67,.16);border-right-color:var(--acid)}

.objective{position:absolute;top:calc(150px + var(--safe-top));left:50%;transform:translateX(-50%);padding:7px 16px;background:rgba(5,11,14,.68);border:1px solid rgba(217,255,67,.18);font-size:8px;letter-spacing:.12em;color:#b5c4bd;opacity:0;transition:opacity .25s;text-align:center;white-space:nowrap}
.objective.show{opacity:1}
.objective b{color:var(--acid)}
.announce{position:absolute;top:24%;left:50%;transform:translate(-50%,-50%);font-family:var(--font-display);font-size:clamp(20px,3.5vw,44px);letter-spacing:.06em;color:var(--acid);text-shadow:0 0 30px rgba(217,255,67,.3),3px 3px 0 rgba(0,0,0,.5);opacity:0;transition:opacity .2s,transform .25s;text-align:center;white-space:nowrap}
.announce.show{opacity:1;transform:translate(-50%,-50%) scale(1.02)}
.announce.danger{color:var(--orange);text-shadow:0 0 30px rgba(255,122,61,.3),3px 3px 0 rgba(0,0,0,.5)}
.announce small{display:block;font-family:var(--font-ui);font-size:9px;letter-spacing:.2em;color:#b4c4bd;margin-top:5px}

.crosshair{position:absolute;top:50%;left:50%;width:34px;height:34px;transform:translate(-50%,-50%);transition:opacity .15s}
.crosshair i{position:absolute;background:rgba(236,246,236,.9);box-shadow:0 0 2px rgba(0,0,0,.9);transition:transform .09s}
.ch-top{width:2px;height:7px;left:16px;top:0}
.ch-bottom{width:2px;height:7px;left:16px;bottom:0}
.ch-left{width:7px;height:2px;left:0;top:16px}
.ch-right{width:7px;height:2px;right:0;top:16px}
.ch-dot{position:absolute;left:16px;top:16px;width:2px;height:2px;background:var(--acid);box-shadow:0 0 4px var(--acid)}
.crosshair.hidden-x{opacity:0}
#hitmarker{position:absolute;top:50%;left:50%;width:30px;height:30px;transform:translate(-50%,-50%) rotate(45deg);opacity:0;transition:opacity .1s}
#hitmarker i{position:absolute;background:var(--acid);box-shadow:0 0 5px rgba(217,255,67,.8)}
#hitmarker i:nth-child(1){width:7px;height:2px;top:0;left:0}
#hitmarker i:nth-child(2){width:7px;height:2px;top:0;right:0}
#hitmarker i:nth-child(3){width:7px;height:2px;bottom:0;left:0}
#hitmarker i:nth-child(4){width:7px;height:2px;bottom:0;right:0}
#hitmarker.show{opacity:1}
#hitmarker.kill i{background:var(--red);box-shadow:0 0 7px var(--red)}
.damage-dirs{position:absolute;top:50%;left:50%;width:200px;height:200px;transform:translate(-50%,-50%);pointer-events:none}
.dmg-dir{position:absolute;width:44px;height:11px;left:78px;top:0;background:linear-gradient(0deg,rgba(255,59,79,.1),rgba(255,59,79,.9));clip-path:polygon(0 100%,50% 0,100% 100%);transform-origin:50% 100px;animation:dmg .65s ease-out forwards}
@keyframes dmg{0%{opacity:1}100%{opacity:0}}

.bottom-left-hud{position:absolute;left:22px;bottom:calc(20px + var(--safe-bottom))}
.health-panel{display:flex;align-items:center;gap:12px;padding:10px 16px 10px 10px;background:linear-gradient(100deg,rgba(5,12,15,.82),rgba(5,12,15,.42));border-left:3px solid var(--acid);clip-path:polygon(0 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%);backdrop-filter:blur(4px)}
.health-icon{width:33px;height:33px;display:grid;place-items:center;background:rgba(217,255,67,.12);border:1px solid rgba(217,255,67,.25);color:var(--acid);font-size:18px}
.health-main span,.armor-main span{display:block;font-size:6px;letter-spacing:.15em;color:#81938c}
.health-main b{display:inline-block;font-family:var(--font-display);font-size:27px;line-height:1;color:#eef5e9}
.health-main i{display:block;width:126px;height:3px;background:rgba(255,255,255,.15);margin-top:4px}
.health-main i em{display:block;height:100%;width:100%;background:linear-gradient(90deg,var(--red),var(--acid));transition:width .2s}
.armor-main{border-left:1px solid rgba(255,255,255,.12);padding-left:12px}
.armor-main b{font-family:var(--font-display);font-size:19px;color:var(--blue);line-height:1.2}
.ability-row{display:flex;gap:4px;margin-top:5px}
.ability{display:flex;align-items:center;gap:5px;padding:4px 8px;background:rgba(5,12,15,.6);border:1px solid rgba(255,255,255,.07);font-size:6px;letter-spacing:.12em;color:#7e9189}
.ability b{color:var(--acid);font-size:10px}
.ability.active{border-color:rgba(217,255,67,.5);color:var(--acid)}
.bottom-right-hud{position:absolute;right:22px;bottom:calc(20px + var(--safe-bottom));text-align:right;min-width:220px}
.weapon-info span{display:block;font-size:11px;font-weight:900;letter-spacing:.14em;color:#e9f1e8}
.weapon-info small{display:block;font-size:6.5px;letter-spacing:.18em;color:#7f928a;margin-top:2px}
.ammo-panel{display:flex;justify-content:flex-end;align-items:baseline;gap:4px;margin-top:1px;text-shadow:0 3px 10px rgba(0,0,0,.8)}
.ammo-panel b{font-family:var(--font-display);font-size:47px;line-height:1;color:#eef5e9}
.ammo-panel>span{font-size:16px;color:#6f837b}
.ammo-panel i{font-style:normal;font-family:var(--font-display);font-size:21px;color:#8b9f96}
.ammo-bar{height:2px;background:rgba(255,255,255,.13);margin:5px 0 6px auto;width:160px}
.ammo-bar em{display:block;height:100%;width:100%;background:var(--acid);transition:width .12s}
.weapon-slots{display:flex;justify-content:flex-end;gap:4px}
.weapon-slots span{font-size:6.5px;letter-spacing:.08em;padding:3px 5px;background:rgba(5,12,15,.58);border:1px solid rgba(255,255,255,.08);color:#71857d}
.weapon-slots span.active{color:var(--acid);border-color:rgba(217,255,67,.35)}
.reload-hint{font-size:6.5px;letter-spacing:.16em;color:var(--orange);margin-top:4px;opacity:0;transition:opacity .15s}
.reload-hint.show{opacity:1;animation:blink .9s steps(2) infinite}
.score-strip{position:absolute;left:50%;bottom:calc(28px + var(--safe-bottom));transform:translateX(-50%);display:flex;gap:18px;padding:5px 13px;background:rgba(4,10,12,.5);border:1px solid rgba(255,255,255,.06)}
.score-strip span{font-size:6.5px;letter-spacing:.12em;color:#73867e}
.score-strip b{color:#dbe7dd;font-size:9px;margin-left:2px}

/* countdown */
.countdown{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(3,8,10,.38);z-index:20}
.countdown span{font-size:10px;letter-spacing:.35em;color:var(--acid);margin-bottom:14px}
.countdown b{font-family:var(--font-display);font-size:clamp(80px,15vw,180px);line-height:.8;color:#fff;text-shadow:0 0 60px rgba(217,255,67,.35),5px 5px 0 rgba(0,0,0,.35);animation:countPop .5s ease-out}
.countdown small{font-size:9px;letter-spacing:.3em;color:#a4b5ae;margin-top:16px}
@keyframes countPop{0%{transform:scale(1.35);opacity:0}100%{transform:scale(1);opacity:1}}

/* pause & scoreboard & end */
.pause-menu{position:absolute;inset:0;z-index:30;display:grid;place-items:center;background:rgba(2,6,8,.7);backdrop-filter:blur(8px);pointer-events:auto}
.pause-panel{width:min(370px,88vw);padding:28px;background:linear-gradient(155deg,rgba(14,25,29,.98),rgba(5,11,14,.98));border:1px solid rgba(217,255,67,.26);clip-path:polygon(0 0,calc(100% - 20px) 0,100% 20px,100% 100%,20px 100%,0 calc(100% - 20px));display:flex;flex-direction:column;gap:9px;text-align:center}
.pause-panel h2{font-family:var(--font-display);font-size:24px;line-height:1.08;margin:4px 0 15px}
.pause-panel .btn-primary,.pause-panel .btn-secondary{width:100%}
.scoreboard{position:absolute;inset:0;z-index:25;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(2,6,8,.72);backdrop-filter:blur(6px);pointer-events:auto;padding:20px}
.scoreboard header{width:min(780px,94vw);display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:rgba(217,255,67,.1);border:1px solid rgba(217,255,67,.3);font-size:9px;font-weight:900;letter-spacing:.18em;color:var(--acid)}
#scoreboard-close{color:#c4d1ca;font-size:12px}
#scoreboard-body{width:min(780px,94vw);max-height:65vh;overflow:auto;background:rgba(5,11,14,.9);border:1px solid rgba(255,255,255,.1);border-top:0}
.sb-row{display:grid;grid-template-columns:1fr 45px 45px 55px;gap:8px;padding:9px 14px;font-size:9px;border-bottom:1px solid rgba(255,255,255,.05)}
.sb-row.head{font-size:7px;letter-spacing:.12em;color:#72867d;background:rgba(255,255,255,.03)}
.sb-row.blue{border-left:2px solid var(--cyan)}
.sb-row.orange{border-left:2px solid var(--orange)}
.sb-row.you{background:rgba(217,255,67,.07)}
.sb-row b{color:#dfe9e1}
.sb-row span{color:#93a69d;text-align:center}
.sb-row span:first-child{text-align:left}
.sb-score{color:var(--acid)!important}

.end-screen{position:absolute;inset:0;z-index:32;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 45%,rgba(217,255,67,.12),transparent 55%),rgba(2,6,8,.86);backdrop-filter:blur(10px);pointer-events:auto;padding:20px}
.end-glow{position:absolute;width:70vw;height:2px;top:24%;background:linear-gradient(90deg,transparent,var(--acid),transparent);box-shadow:0 0 60px 15px rgba(217,255,67,.18)}
#end-kicker{position:relative;letter-spacing:.4em;color:var(--acid);margin-bottom:10px}
#end-title{position:relative;font-family:var(--font-display);font-size:clamp(58px,10vw,130px);line-height:.85;letter-spacing:.04em;text-shadow:0 0 60px rgba(217,255,67,.28),6px 6px 0 rgba(0,0,0,.4);text-align:center}
#end-screen.defeat #end-title{color:var(--orange);text-shadow:0 0 60px rgba(255,122,61,.24),6px 6px 0 rgba(0,0,0,.4)}
#end-sub{position:relative;font-size:10px;letter-spacing:.12em;color:#a9bab3;margin:12px 0 18px;text-align:center}
.end-mvp{position:relative;display:flex;align-items:center;gap:12px;padding:10px 18px 10px 10px;background:rgba(217,255,67,.08);border:1px solid rgba(217,255,67,.25);margin-bottom:16px}
.end-mvp img{width:52px;height:52px;object-fit:cover;background:#0b1619}
.end-mvp div b{display:block;font-size:11px;letter-spacing:.1em}
.end-mvp div span{display:block;font-size:8px;color:var(--acid);letter-spacing:.15em;margin-top:3px}
.end-scoreboard{position:relative;width:min(600px,92vw);max-height:31vh;overflow:auto;background:rgba(5,11,14,.8);border:1px solid rgba(255,255,255,.09)}
.end-actions{position:relative;display:flex;gap:10px;margin-top:20px}

/* mobile controls */
.mobile-controls{position:absolute;inset:0;pointer-events:none;z-index:15}
.look-zone{position:absolute;right:0;top:18%;width:58%;height:56%;pointer-events:auto;touch-action:none}
.joystick{position:absolute;left:20px;bottom:calc(24px + var(--safe-bottom));width:116px;height:116px;border-radius:50%;background:radial-gradient(circle,rgba(217,255,67,.06),rgba(4,10,12,.4));border:1px solid rgba(217,255,67,.22);pointer-events:auto;touch-action:none}
.joystick-ring{position:absolute;inset:20px;border-radius:50%;border:1px dashed rgba(255,255,255,.16)}
.joystick-knob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(217,255,67,.55),rgba(50,80,20,.5));border:1px solid rgba(217,255,67,.55);box-shadow:0 0 18px rgba(217,255,67,.2)}
.touch-actions{position:absolute;right:18px;bottom:calc(24px + var(--safe-bottom));width:176px;height:176px;pointer-events:none}
.touch-btn{position:absolute;pointer-events:auto;touch-action:none;border-radius:50%;background:rgba(6,13,15,.62);border:1px solid rgba(255,255,255,.18);color:#d5e1da;font-size:9px;font-weight:900;letter-spacing:.08em;backdrop-filter:blur(3px)}
.touch-btn:active{background:rgba(217,255,67,.22);border-color:var(--acid)}
.touch-btn.fire{right:0;bottom:0;width:82px;height:82px;border-color:rgba(217,255,67,.46);background:radial-gradient(circle at 35% 30%,rgba(217,255,67,.22),rgba(7,14,16,.72));box-shadow:0 0 26px rgba(217,255,67,.1)}
.touch-btn.fire span{font-size:32px;color:var(--acid);line-height:1}
.touch-btn.small{width:48px;height:48px}
#btn-ads{right:88px;bottom:8px}
#btn-jump{right:12px;bottom:88px}
#btn-reload{right:69px;bottom:69px;width:44px;height:44px}
.mobile-controls .touch-btn.small{font-size:8px}

.toast{position:absolute;z-index:80;left:50%;bottom:12%;transform:translateX(-50%);padding:9px 16px;background:rgba(5,11,14,.92);border-left:2px solid var(--acid);font-size:9px;letter-spacing:.1em;color:#d9e5dc;pointer-events:none;transition:opacity .25s,transform .25s}
.toast.show{opacity:1;transform:translateX(-50%) translateY(-4px)}

/* ============================== RESPONSIVE ============================== */
@media (max-width:1180px){
  .game-title em{font-size:clamp(64px,9vw,102px)}
  .menu-left{width:min(580px,55vw)}
  .operator-panel{width:310px}
  .bottom-nav button{padding:7px 7px;font-size:7px}
  .weapon-slot{min-width:230px}
}
@media (max-width:980px){
  .topbar-right{gap:10px}
  .season-chip{display:none}
  .menu-body{padding-bottom:0}
  .menu-left{width:min(540px,59vw)}
  .game-title span{font-size:clamp(20px,3vw,30px)}
  .game-title em{font-size:clamp(58px,8.5vw,84px)}
  .game-subtitle{font-size:10.5px;max-width:430px}
  .mode-card small{font-size:7.5px}
  .operator-panel{width:270px;padding:13px 14px 11px;bottom:10px}
  .operator-copy p{font-size:9px;min-height:42px}
  .char-stats{display:none}
  .menu-bottom{gap:10px;padding-top:8px;padding-bottom:10px}
  .loadout-meta,.loadout-divider{display:none}
  .bottom-nav button{padding:6px 5px;font-size:6.5px}
  .build-tag{display:none}
  .weapon-slot{min-width:205px}
  .roster-grid{grid-template-columns:repeat(4,1fr)}
  .map-detail-grid{grid-template-columns:repeat(3,1fr)}
  .arsenal-layout{grid-template-columns:1fr;gap:16px}
  .skin-panel{border-left:0;padding-left:0;border-top:1px solid var(--line-soft);padding-top:15px;display:grid;grid-template-columns:1.2fr 1fr;gap:14px;align-items:start}
  .skin-preview{margin:0;grid-row:span 3;height:150px}
  .custom-grid{grid-template-columns:1fr 1fr}
  .custom-summary{grid-column:1/-1;flex-direction:row;text-align:left;justify-content:flex-start}
  .custom-summary .btn-primary{margin-left:auto}
}
@media (max-width:760px){
  .topbar{padding:12px 15px 0;padding-top:calc(12px + var(--safe-top))}
