  .brand-type strong{font-size:15px}
  .brand-type span{font-size:7px;letter-spacing:.22em}
  .profile-meta,.profile-level{display:none}
  .profile-chip{padding:4px}
  .profile-avatar{width:32px;height:32px}
  .menu-screen{background:linear-gradient(0deg,rgba(4,9,11,.97),rgba(4,9,11,.55) 56%,rgba(3,7,9,.36)),radial-gradient(ellipse 100% 50% at 70% 32%,rgba(255,122,61,.15),transparent 70%)}
  .menu-body{display:block;padding:0 15px;overflow:auto;padding-bottom:8px}
  .menu-left{width:100%;padding-top:6px}
  .season-tag{font-size:7px;margin-bottom:9px;padding:5px 8px}
  .game-title{margin-bottom:9px}
  .game-title span{font-size:16px;letter-spacing:.25em}
  .game-title em{font-size:clamp(57px,16vw,78px);margin-left:-2px}
  .game-subtitle{font-size:9px;line-height:1.45;margin-bottom:13px}
  .game-subtitle br{display:none}
  .section-label{font-size:7.5px;margin-bottom:6px}
  .mode-list{gap:4px}
  .mode-card{padding:8px 7px;gap:2px}
  .mode-icon{font-size:11px}
  .mode-card b{font-size:8px;letter-spacing:.04em}
  .mode-card small{font-size:6px}
  .mode-card .mode-check{display:none}
  .map-label{margin-top:9px}
  .map-strip{gap:4px}
  .map-card{flex-basis:78px;height:42px}
  .map-card span{font-size:5.5px;padding:2px 4px}
  .play-row{margin-top:11px;gap:5px}
  .play-btn{padding:9px 12px 9px 10px;gap:9px}
  .play-chevron{width:27px;height:27px;font-size:10px}
  .play-text b{font-size:22px}
  .play-text small{font-size:6.5px}
  .play-badge{font-size:8px;padding:4px 5px}
  .square-btn{flex-basis:54px}
  .square-btn span{font-size:15px}
  .square-btn small{font-size:5px}
  .operator-panel{position:absolute;right:15px;bottom:68px;width:min(240px,53vw);padding:10px 12px;background:linear-gradient(160deg,rgba(7,14,17,.8),rgba(7,14,17,.32))}
  .operator-topline{padding-bottom:5px;margin-bottom:7px}
  .operator-id{font-size:11px}
  .char-role{font-size:6px}
  .operator-copy h2{font-size:17px;margin-bottom:6px}
  .operator-copy p{display:none}
  .anim-buttons{display:none}
  .operator-pager{margin-top:7px}
  .operator-dots{display:none}
  .operator-pager button{height:18px}
  .menu-bottom{padding:7px 15px calc(7px + var(--safe-bottom));flex-direction:column;align-items:stretch;gap:6px;background:rgba(3,8,10,.88);position:relative}
  .loadout-strip{width:100%}
  .loadout-label{display:none}
  .weapon-slot{flex:1;min-width:0;max-width:none;padding:4px 8px}
  .weapon-silhouette{width:60px;height:28px}
  .weapon-silhouette svg{width:56px;height:22px}
  .weapon-slot b{font-size:8.5px}
  .weapon-slot span{font-size:6px}
  .loadout-meta{display:none}
  .bottom-nav{justify-content:space-between;width:100%}
  .bottom-nav button{font-size:6px;padding:4px 3px;flex:1;text-align:center}
  .bottom-nav button b{display:none}
  .top-hud{top:calc(58px + var(--safe-top))}
  .minimap-wrap{top:calc(106px + var(--safe-top));left:10px}
  .minimap-ring{width:91px;height:91px}
  .zone-chips{display:none}
  .killfeed{top:calc(104px + var(--safe-top));right:10px;max-width:210px}
  .kill-item{font-size:6.5px;padding:3px 5px}
  .objective{top:calc(150px + var(--safe-top));font-size:6.5px;padding:5px 9px;white-space:normal;width:70vw}
  .bottom-left-hud{left:10px;bottom:calc(154px + var(--safe-bottom))}
  .health-panel{padding:6px 10px 6px 6px;gap:7px}
  .health-icon{width:25px;height:25px;font-size:13px}
  .health-main b{font-size:20px}
  .health-main i{width:76px}
  .health-main span,.armor-main span{font-size:5px}
  .armor-main{padding-left:7px}
  .armor-main b{font-size:14px}
  .ability-row{display:none}
  .bottom-right-hud{right:10px;bottom:calc(154px + var(--safe-bottom));min-width:150px}
  .weapon-info span{font-size:8px}
  .weapon-info small{font-size:5px}
  .ammo-panel b{font-size:33px}
  .ammo-panel i{font-size:15px}
  .ammo-bar{width:110px}
  .weapon-slots{display:none}
  .reload-hint{font-size:5.5px}
  .score-strip{display:none}
  .crosshair{width:28px;height:28px}
  .ch-top,.ch-bottom{height:6px;left:13px}
  .ch-left,.ch-right{width:6px;top:13px}
  .ch-dot{left:13px;top:13px}
  .announce{top:27%;font-size:26px;white-space:normal;width:80vw}
  .mobile-controls{display:block}
  .joystick{width:100px;height:100px;left:14px;bottom:calc(66px + var(--safe-bottom))}
  .joystick-knob{width:40px;height:40px;margin:-20px 0 0 -20px}
  .touch-actions{right:10px;bottom:calc(66px + var(--safe-bottom));width:158px;height:150px}
  .touch-btn.fire{width:72px;height:72px}
  .touch-btn.small{width:42px;height:42px}
