  const rarm = new THREE.Mesh(new THREE.BoxGeometry(.18, .18, .52), sleeve);
  rarm.position.copy(rightPos).add(new THREE.Vector3(.09, -.1, .26)); rarm.rotation.x = .18; g.add(rarm);
  // left hand on handguard
  const lh = new THREE.Mesh(new THREE.BoxGeometry(.15, .14, .18), skin);
  lh.position.copy(leftPos); g.add(lh);
  for (let i = 0; i < 3; i++) {
    const f = new THREE.Mesh(new THREE.BoxGeometry(.15, .045, .055), skin);
    f.position.copy(leftPos).add(new THREE.Vector3(0, .03 - i * .05, -.07)); g.add(f);
  }
  const larm = new THREE.Mesh(new THREE.BoxGeometry(.17, .17, .55), sleeve);
  larm.position.copy(leftPos).add(new THREE.Vector3(-.05, -.14, .28)); larm.rotation.x = .32; g.add(larm);
